    raw,
    fuentes,
    nombre,
    ahora,
    web?.competidores?.length || web?.comprobaciones?.length
      ? "youtube_data_api_y_web"
      : "youtube_data_api",
  );
  if (
    resultado.competidores.some((c) =>
      c.muestras.some((v) => v.formato === "sin_clasificar"),
    )
